(async () => {
  const sleep = ms => new Promise(r => setTimeout(r, ms));
  const webRb = document.getElementById('main_web_rd') || document.getElementById('modal_web_rd');
  if (webRb) { try { webRb.click(); } catch(e) {} }
  await sleep(800);
  const btns = Array.from(document.querySelectorAll('button')).filter(b => b.offsetParent!==null).map(b=>(b.innerText||'').replace(/\s+/g,' ').trim()).filter(Boolean);
  let clicked = '';
  const loginBtn = Array.from(document.querySelectorAll('button')).find(b => /^Login/i.test((b.innerText||'').replace(/\s+/g,' ').trim()) && b.offsetParent!==null);
  if (loginBtn) { loginBtn.click(); clicked = (loginBtn.innerText||'').replace(/\s+/g,' '); }
  await sleep(10000);
  return JSON.stringify({clicked, url: location.href, title: document.title,
    inputs: Array.from(document.querySelectorAll('input')).filter(i=>i.offsetParent!==null).map(i=>i.id).slice(0,8),
    txt: (document.body.innerText||'').replace(/\s+/g,' ').slice(0,200)
  });
})()
